(O/'decision_log.json').write_text(json.dumps({'aeris_workspace':'/output/aeris-workspace/.aeris','decisions':['Locked PM10-only target before retrieval.','Excluded prohibited published exposure and deposited infection values.','Used public DPC provincial outcome snapshots and Mendeley sampling/density fields.','Completed all 28 deterministic AERIS batches before coverage evaluation.','Used every observed positive-count unit for the locked log-log fit.']},indent=2))
effects=[]
for date,m in model['models'].items():
 effects.append({'label':'COVID-19 infections '+date,'primary':date=='20200407','estimate':m['outcome_ratio_per_doubling_pm10_exceedance_days'],'ci_low':m['outcome_ratio_ci95'][0],'ci_high':m['outcome_ratio_ci95'][1],'scale':'ratio','contrast':'doubling annual 2018 PM10 >50 ug/m3 day count','metric':'outcome_ratio','native_estimate':m['pm10_beta'],'native_ci_low':m['pm10_beta_ci95'][0],'native_ci_high':m['pm10_beta_ci95'][1],'native_scale':'log-log OLS coefficient','native_contrast':'one-unit increase in log PM10 count'})
panel=pd.read_csv(D/'analysis_panel.csv'); fit=panel.query('eligible_loglog')
handoff={'schema_version':1,'study_id':'33398753-italy-cities','status':'fitted','fidelity':'reduced_coverage','target':{'outcome':'Cumulative confirmed COVID-19 infections on 17 March, 7 April, and 27 April 2020','pollutant':'PM10','geography':'55 Italian provincial-capital cities','population':'Residents of sampled provincial-capital cities','period':'2018 exposure; 2020 outcomes','effect_scale':'Outcome ratio per doubling annual PM10 exceedance-day count','exposure_assignment':'Nearest monitor within 100 km of provincial-capital reference coordinate; daily series','model':'OLS of log cumulative infections on log PM10 exceedance days and log 2019 population density','covariates':['2019 population density (log)'],'named_outcome_source':'Italian Ministry of Health / public Protezione Civile provincial archive substitution','specification_evidence':['/study/article.md','/run/contract/study-target.json']},'sources':sources,'substitutions':[{'dimension':'exposure','change_type':'source','published':'Regional environmental agencies/Legambiente','reanalysis':'OpenAQ v3 plus public S3 historical archive','reason':'Independently retrieved monitor observations; published exposure values excluded.'},{'dimension':'outcome','change_type':'source','published':'Ministero della Salute','reanalysis':'Protezione Civile provincial archive','reason':'Public historical cumulative snapshots available for all article dates.'},{'dimension':'exposure','change_type':'coverage_subset','published':'55 cities','reanalysis':'32 positive-count complete cases','reason':'13 missing series and 10 zero counts make log exposure undefined.'}],'coverage':{'eligible_units':55,'included_units':32,'eligible_times':365,'included_times':None,'rule':'All units with retrieved series and strictly positive PM10>50 annual count; no numeric coverage cutoff.','notes':'42 units had 284–343 observed days; 10 had zero count and 13 had no series.'},'effects':effects,'analysis_diagnostics':{'observations':32,'estimated_parameters':3,'exposure_unique_values':int(fit.pm10_exceedance_days_gt50.nunique()),'outcome_unique_values':int(fit.infections_20200407.nunique()),'joined_rows':55,'unmatched_outcome_rows':0,'unmatched_exposure_rows':13,'contrast_transformation_verified':True,'reported_variants':['17 March 2020','7 April 2020','27 April 2020']},'artifacts':{'code':'/output/code','source_manifest':'/output/source_manifest.json','exposure':'/output/data/pm10_exposure_2018.csv','analysis_panel':'/output/data/analysis_panel.csv','model_output':'/output/model_output.json','decision_log':'/output/decision_log.json','research_notebook':'/output/aeris-workspace/.aeris/research-notebook.json','blocker_ledger':'/output/blocker_ledger.md','fidelity_record':'/output/aeris-workspace/.aeris/artifacts/reanalysis-fidelity_reanalysis-fidelity_2026-09-25T222340.8978740000.json','coverage_diagnostics':'/output/coverage_diagnostics.md','boundary_route_evidence':'/output/data/aeris_city_cohort.csv','study_contract':'/output/aeris-workspace/.aeris/contracts/agent-contract-amendment-001.json'},'blockers':[]}
